import{_ as a,a as t,c as s,ac as n}from"./chunks/framework.BSuaGltH.js";const k=JSON.parse('{"title":"Python 环境：解释器、首次运行与虚拟环境","description":"按安装、确认解释器、运行脚本、隔离依赖和开发检查组织。","frontmatter":{"title":"Python 环境：解释器、首次运行与虚拟环境","description":"按安装、确认解释器、运行脚本、隔离依赖和开发检查组织。","showdocs":{"topics":[{"id":"python","title":"Python","link":"/topics/python/"}],"kind":"知识专题","scope":"general","audience":"general","group":"语言与开发","seriesTitle":"Python 系统学习","summary":"按安装、确认解释器、运行脚本、隔离依赖和开发检查组织。","status":"active","related":[{"title":"Django 入门：项目、路由与请求链","link":"/programming/python/django-request-model","kind":"开发实践","scope":"general","audience":"general"},{"title":"Django常见故障的定位顺序","link":"/programming/python/plus/troubleshooting/django-diagnostics","kind":"排错","scope":"general","audience":"general"},{"title":"Django个人任务板完整实践","link":"/programming/python/plus/practice/django-application","kind":"开发实践","scope":"general","audience":"general"},{"title":"Django个人任务板完整实践 · Django任务板完整工程包含哪些文件至全部工程文件与同源正文","link":"/programming/python/plus/practice/django-application-part-01","kind":"开发实践","scope":"general","audience":"general"},{"title":"Django个人任务板完整实践 · tasks/urls.py至版本与资料边界","link":"/programming/python/plus/practice/django-application-part-02","kind":"开发实践","scope":"general","audience":"general"}],"prev":{"text":"Python 学习路线与资料","link":"/programming/python/base/basic/1-base"},"next":{"text":"Python 值与序列：类型、切片、列表和队列","link":"/programming/python/values-and-sequences"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Python 学习路线与资料","link":"/programming/python/base/basic/1-base"},"next":{"text":"Python 值与序列：类型、切片、列表和队列","link":"/programming/python/values-and-sequences"}},"headers":[],"relativePath":"programming/python/environment.md","filePath":"programming/python/environment.md"}'),i={name:"programming/python/environment.md"};function p(o,e,r,l,h,d){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="python-环境-解释器、首次运行与虚拟环境" tabindex="-1">Python 环境：解释器、首次运行与虚拟环境 <a class="header-anchor" href="#python-环境-解释器、首次运行与虚拟环境" aria-label="Permalink to &quot;Python 环境：解释器、首次运行与虚拟环境&quot;">​</a></h1><h2 id="part-1" tabindex="-1">Python 安装与首次运行 <a class="header-anchor" href="#part-1" aria-label="Permalink to &quot;Python 安装与首次运行 {#part-1}&quot;">​</a></h2><p><span id="part-1-python-install"></span><span id="part-1-python-install-1"></span></p><h3 id="part-1-install" tabindex="-1">选择安装方式 <a class="header-anchor" href="#part-1-install" aria-label="Permalink to &quot;选择安装方式 {#part-1-install}&quot;">​</a></h3><p>先看项目要求的 Python 版本。macOS 和 Windows 可从 <a href="https://www.python.org/downloads/" target="_blank" rel="noopener noreferrer">Python 官方下载页</a>选择对应平台安装方式；Linux 优先使用发行版提供的 Python 3 包。不要替换系统管理工具依赖的 Python。</p><p>Linux 的包名、安装权限和更新周期由发行版决定。例如 Debian/Ubuntu 常见为 <code>python3</code>、<code>python3-venv</code>、<code>python3-pip</code>；这些名字不是所有 Linux 都通用。</p><p>已有 Homebrew、系统包管理器或版本管理器时，优先沿用项目约定，避免为了“升级”而叠加另一套全局安装。</p><h3 id="part-1-verify" tabindex="-1">验证实际解释器 <a class="header-anchor" href="#part-1-verify" aria-label="Permalink to &quot;验证实际解释器 {#part-1-verify}&quot;">​</a></h3><p>安装完成后新开终端。Windows 通常可用 <code>python</code> 或 <code>py</code>，macOS/Linux 通常用 <code>python3</code>；以下正文统一写 <code>python</code>，请替换成自己验证过的命令。</p><div class="language-shell vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;import sys; print(sys.executable)&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>第一行确认版本，第二行确认完整路径，第三行确认 pip 属于同一个解释器。找不到 pip 时按所用安装渠道的文档补装，不要盲目用另一条 <code>pip</code> 命令。 若终端与 IDE 显示相同版本却导入出不同的包，继续比较两边的 <code>sys.executable</code> 和 <code>python -m pip --version</code> 报告的包目录。</p><p>Windows 若跳到 Microsoft Store 或只显示应用执行别名，说明当前命令尚未解析到可用解释器；检查安装情况与 PATH，再重开终端。IDE 中也应选择相同解释器。</p><h3 id="part-1-repl" tabindex="-1">交互执行 <a class="header-anchor" href="#part-1-repl" aria-label="Permalink to &quot;交互执行 {#part-1-repl}&quot;">​</a></h3><p>解释器负责执行 Python 程序；编辑器和 IDE 是编写、调试程序的工具，仍需选择解释器。CPython 是常见实现，不能把其字节码机制当成所有实现的语言定义。</p><p>终端运行 <code>python</code> 进入 REPL。<code>&gt;&gt;&gt;</code> 是提示符，不要复制进 <code>.py</code> 文件。</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&gt;&gt;&gt; 2 + 3</span></span>
<span class="line"><span>5</span></span>
<span class="line"><span>&gt;&gt;&gt; print(&quot;hello, Python&quot;)</span></span>
<span class="line"><span>hello, Python</span></span>
<span class="line"><span>&gt;&gt;&gt; help(print)</span></span></code></pre></div><p>多行定义以空行结束；用 <code>exit()</code> 离开。REPL 适合试表达式，正式程序保存为脚本。</p><h3 id="part-1-execute" tabindex="-1">首次运行脚本 <a class="header-anchor" href="#part-1-execute" aria-label="Permalink to &quot;首次运行脚本 {#part-1-execute}&quot;">​</a></h3><p>把下面一行保存为 <code>hello.py</code>。终端先进入文件所在目录，再运行 <code>python hello.py</code>，应输出 <code>hello, Python</code>。交互提示符 <code>&gt;&gt;&gt;</code> 不写入文件。</p><div class="language-python vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;hello, Python&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>交互执行便于试一行代码，脚本则保存可以重复运行的步骤。函数、命令行参数和 <code>-m</code> 执行模块在 <a href="/programming/python/base/basic/8-function#entry">函数、模块与包</a>中继续学习。</p><h3 id="part-1-next" tabindex="-1">下一步与练习 <a class="header-anchor" href="#part-1-next" aria-label="Permalink to &quot;下一步与练习 {#part-1-next}&quot;">​</a></h3><p>在交互提示符和 <code>hello.py</code> 中分别修改问候文字，确认两种方式的输出，再按 <a href="#part-2-venv">开发环境</a>为项目创建 <code>.venv</code>。</p><p>完整平台选项见 <a href="https://docs.python.org/3/using/windows.html" target="_blank" rel="noopener noreferrer">Windows 使用说明</a>、<a href="https://docs.python.org/3/using/mac.html" target="_blank" rel="noopener noreferrer">macOS 使用说明</a> 和 <a href="https://docs.python.org/3/using/unix.html" target="_blank" rel="noopener noreferrer">Unix 使用说明</a>。安装器界面和命令可能随版本变化，以对应版本文档为准。</p><h3 id="part-1-answers" tabindex="-1">练习核对 <a class="header-anchor" href="#part-1-answers" aria-label="Permalink to &quot;练习核对 {#part-1-answers}&quot;">​</a></h3><p>两处都改成 <code>print(&quot;hello, learner&quot;)</code> 时，REPL当场显示该文本；脚本必须保存后从其所在目录运行，才会显示同一行。只修改REPL不会改变磁盘上的hello.py。建立 <code>.venv</code> 后打印 <code>sys.executable</code>，预期路径位于该项目的 <code>.venv</code>；若仍指向系统目录，先检查实际使用的命令或IDE解释器。直接执行 <code>.venv</code> 中的解释器也可观察同一路径。</p><h2 id="part-2" tabindex="-1">Python 虚拟环境与开发工具 <a class="header-anchor" href="#part-2" aria-label="Permalink to &quot;Python 虚拟环境与开发工具 {#part-2}&quot;">​</a></h2><p><span id="part-2-python-utilcmd"></span></p><h3 id="part-2-venv" tabindex="-1">项目虚拟环境 <a class="header-anchor" href="#part-2-venv" aria-label="Permalink to &quot;项目虚拟环境 {#part-2-venv}&quot;">​</a></h3><p><code>venv</code> 是标准库提供的虚拟环境工具，用于隔离项目安装的包；无需为了创建环境先安装第三方 <code>virtualenv</code>。它隔离依赖，不隔离操作系统权限。</p><div class="language-shell vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> venv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .venv</span></span></code></pre></div><p>按当前 shell 激活：</p><table tabindex="0"><thead><tr><th>环境</th><th>命令</th></tr></thead><tbody><tr><td>PowerShell</td><td><code>.\\.venv\\Scripts\\Activate.ps1</code></td></tr><tr><td>Windows cmd</td><td><code>.venv\\Scripts\\activate.bat</code></td></tr><tr><td>macOS/Linux bash、zsh</td><td><code>source .venv/bin/activate</code></td></tr></tbody></table><p>激活后运行 <code>python -c &quot;import sys; print(sys.executable)&quot;</code> 确认路径，<code>deactivate</code> 退出。激活脚本会调整当前 shell 的 PATH 等环境变量。直接运行 <code>.venv</code> 内的解释器同样能选中环境，运行时通常可用 <code>sys.prefix != sys.base_prefix</code> 判断是否在 venv 中。PowerShell 无法运行激活脚本时可先用 <code>.\\.venv\\Scripts\\python.exe</code>，不必修改全局执行策略。详见 <a href="https://docs.python.org/3/library/venv.html" target="_blank" rel="noopener noreferrer">venv 文档</a>。</p><h3 id="part-2-pip" tabindex="-1">依赖操作 <a class="header-anchor" href="#part-2-pip" aria-label="Permalink to &quot;依赖操作 {#part-2-pip}&quot;">​</a></h3><div class="language-shell vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> requests</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> requirements.txt</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> uninstall</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> requests</span></span></code></pre></div><p>安装命令会访问包索引；示例包不是本系列的必需依赖。团队项目优先按已提交的依赖清单安装，不任意升级到 latest。<code>pip freeze</code> 能输出当前环境快照，但不等于自动解决跨平台兼容性或锁定所有外部工具。</p><h3 id="part-2-tools" tabindex="-1">测试与检查 <a class="header-anchor" href="#part-2-tools" aria-label="Permalink to &quot;测试与检查 {#part-2-tools}&quot;">​</a></h3><p>先看项目已有配置与命令。标准库测试可运行 <code>python -m unittest discover</code>；项目使用 pytest 时才安装并运行 pytest。</p><p>学会函数后可先用 <code>assert</code> 检查返回值；需要组织独立测试时，完整的标准库 <code>unittest</code> 示例见 <a href="/programming/python/base/intermediate/11-class#testing">类与实例中的测试练习</a>。初次配置环境时先确认命令使用同一解释器即可。</p><p>Pylint、autopep8、coverage 等均是按项目选用的第三方工具，不属于语言内置命令。例如已安装 coverage 和 pytest 时可用 <code>python -m coverage run -m pytest</code>、<code>python -m coverage html</code>。报告格式依工具实际支持项选择，不能假定 Pylint 内置 HTML 输出。</p><h3 id="part-2-practice" tabindex="-1">练习 <a class="header-anchor" href="#part-2-practice" aria-label="Permalink to &quot;练习 {#part-2-practice}&quot;">​</a></h3><p>在虚拟环境内外分别打印解释器路径。学完类以后，再在虚拟环境中运行上述链接的标准库测试。能够解释“包安装到了一个环境，程序却在另一个环境运行”时为什么会出现 <code>ModuleNotFoundError</code>。</p><h3 id="part-2-answers" tabindex="-1">练习核对 <a class="header-anchor" href="#part-2-answers" aria-label="Permalink to &quot;练习核对 {#part-2-answers}&quot;">​</a></h3><p>提示：比较完整路径，不只比较版本号。虚拟环境内应指向 <code>.venv/Scripts/python.exe</code>（Windows）或 <code>.venv/bin/python</code>（Unix），环境外应指向原解释器；直接调用虚拟环境路径也有效。两个环境即使版本相同，包搜索目录仍可不同，所以A环境安装的包不保证B环境可导入。类课的 <code>test_total.py</code> 保存后，需进入其目录再用所选解释器执行 <code>-m unittest test_total</code>，预期一个测试通过。随后可用<a href="/programming/python/plus/practice/unittest-files">临时目录中的文件测试</a>区分测试发现、模块导入和文件路径问题。</p>`,45)])])}const g=a(i,[["render",p]]);export{k as __pageData,g as default};
